package session

import (
	"fmt"
	"strings"
)

// Phase represents the lifecycle stage of a session.
type Phase string

const (
	PhaseActive          Phase = "active"
	PhaseActiveCommitted Phase = "active_committed"
	PhaseIdle            Phase = "idle"
	PhaseEnded           Phase = "ended"
)

// allPhases is the canonical list of phases for enumeration (e.g., diagram generation).
var allPhases = []Phase{PhaseIdle, PhaseActive, PhaseActiveCommitted, PhaseEnded}

// PhaseFromString normalizes a phase string, treating empty or unknown values
// as PhaseIdle for backward compatibility with pre-state-machine session files.
func PhaseFromString(s string) Phase {
	switch Phase(s) {
	case PhaseActive:
		return PhaseActive
	case PhaseActiveCommitted:
		return PhaseActiveCommitted
	case PhaseIdle:
		return PhaseIdle
	case PhaseEnded:
		return PhaseEnded
	default:
		return PhaseIdle
	}
}

// IsActive reports whether the phase represents an active agent turn.
func (p Phase) IsActive() bool {
	return p == PhaseActive || p == PhaseActiveCommitted
}

// Event represents something that happened to a session.
type Event int

const (
	EventUserPromptSubmit Event = iota // Agent received a new user prompt
	EventStop                          // Agent turn ended (Stop hook)
	EventGitCommit                     // A git commit was made (PostCommit hook)
	EventSessionStart                  // Session process started (SessionStart hook)
	EventSessionStop                   // Session process ended (SessionStop hook)
)

// allEvents is the canonical list of events for enumeration.
var allEvents = []Event{EventUserPromptSubmit, EventStop, EventGitCommit, EventSessionStart, EventSessionStop}

// String returns a human-readable name for the event.
func (e Event) String() string {
	switch e {
	case EventUserPromptSubmit:
		return "UserPromptSubmit"
	case EventStop:
		return "Stop"
	case EventGitCommit:
		return "GitCommit"
	case EventSessionStart:
		return "SessionStart"
	case EventSessionStop:
		return "SessionStop"
	default:
		return fmt.Sprintf("Event(%d)", int(e))
	}
}

// Action represents a side effect that should be performed after a transition.
// The caller is responsible for executing these -- the state machine only declares them.
type Action int

const (
	ActionCondense               Action = iota // Condense session data to permanent storage
	ActionCondenseIfFilesTouched               // Condense only if FilesTouched is non-empty
	ActionDiscardIfNoFiles                     // Discard session if FilesTouched is empty
	ActionMigrateShadowBranch                  // Migrate shadow branch to new HEAD
	ActionWarnStaleSession                     // Warn user about stale session(s)
	ActionClearEndedAt                         // Clear EndedAt timestamp (session re-entering)
	ActionUpdateLastInteraction                // Update LastInteractionTime
)

// String returns a human-readable name for the action.
func (a Action) String() string {
	switch a {
	case ActionCondense:
		return "Condense"
	case ActionCondenseIfFilesTouched:
		return "CondenseIfFilesTouched"
	case ActionDiscardIfNoFiles:
		return "DiscardIfNoFiles"
	case ActionMigrateShadowBranch:
		return "MigrateShadowBranch"
	case ActionWarnStaleSession:
		return "WarnStaleSession"
	case ActionClearEndedAt:
		return "ClearEndedAt"
	case ActionUpdateLastInteraction:
		return "UpdateLastInteraction"
	default:
		return fmt.Sprintf("Action(%d)", int(a))
	}
}

// TransitionContext provides read-only context for transitions that need
// to inspect session state without mutating it.
type TransitionContext struct {
	HasFilesTouched    bool // len(FilesTouched) > 0
	IsRebaseInProgress bool // .git/rebase-merge/ or .git/rebase-apply/ exists
}

// TransitionResult holds the outcome of a state machine transition.
type TransitionResult struct {
	NewPhase Phase
	Actions  []Action
}

// Transition computes the next phase and required actions given the current
// phase and an event. This is a pure function with no side effects.
//
// Empty or unknown phase values are normalized to PhaseIdle for backward
// compatibility with session state files created before phase tracking.
func Transition(current Phase, event Event, ctx TransitionContext) TransitionResult {
	// Normalize empty/unknown phase to idle for backward compatibility.
	current = PhaseFromString(string(current))

	switch current {
	case PhaseIdle:
		return transitionFromIdle(event, ctx)
	case PhaseActive:
		return transitionFromActive(event, ctx)
	case PhaseActiveCommitted:
		return transitionFromActiveCommitted(event, ctx)
	case PhaseEnded:
		return transitionFromEnded(event, ctx)
	default:
		// PhaseFromString guarantees we only get known phases, but the
		// exhaustive linter requires handling the default case.
		return TransitionResult{NewPhase: PhaseIdle}
	}
}

func transitionFromIdle(event Event, ctx TransitionContext) TransitionResult {
	switch event {
	case EventUserPromptSubmit:
		return TransitionResult{
			NewPhase: PhaseActive,
			Actions:  []Action{ActionUpdateLastInteraction},
		}
	case EventStop:
		// Stop while idle is a no-op (no active turn to end).
		return TransitionResult{NewPhase: PhaseIdle}
	case EventGitCommit:
		if ctx.IsRebaseInProgress {
			return TransitionResult{NewPhase: PhaseIdle}
		}
		return TransitionResult{
			NewPhase: PhaseIdle,
			Actions:  []Action{ActionCondense, ActionUpdateLastInteraction},
		}
	case EventSessionStart:
		// Already condensable, no-op.
		return TransitionResult{NewPhase: PhaseIdle}
	case EventSessionStop:
		return TransitionResult{
			NewPhase: PhaseEnded,
			Actions:  []Action{ActionUpdateLastInteraction},
		}
	default:
		return TransitionResult{NewPhase: PhaseIdle}
	}
}

func transitionFromActive(event Event, ctx TransitionContext) TransitionResult {
	switch event {
	case EventUserPromptSubmit:
		// Ctrl-C recovery: just continue.
		return TransitionResult{
			NewPhase: PhaseActive,
			Actions:  []Action{ActionUpdateLastInteraction},
		}
	case EventStop:
		return TransitionResult{
			NewPhase: PhaseIdle,
			Actions:  []Action{ActionUpdateLastInteraction},
		}
	case EventGitCommit:
		if ctx.IsRebaseInProgress {
			return TransitionResult{NewPhase: PhaseActive}
		}
		return TransitionResult{
			NewPhase: PhaseActiveCommitted,
			Actions:  []Action{ActionMigrateShadowBranch, ActionUpdateLastInteraction},
		}
	case EventSessionStart:
		return TransitionResult{
			NewPhase: PhaseActive,
			Actions:  []Action{ActionWarnStaleSession},
		}
	case EventSessionStop:
		return TransitionResult{
			NewPhase: PhaseEnded,
			Actions:  []Action{ActionUpdateLastInteraction},
		}
	default:
		return TransitionResult{NewPhase: PhaseActive}
	}
}

func transitionFromActiveCommitted(event Event, ctx TransitionContext) TransitionResult {
	switch event {
	case EventUserPromptSubmit:
		// Ctrl-C recovery after commit.
		return TransitionResult{
			NewPhase: PhaseActive,
			Actions:  []Action{ActionUpdateLastInteraction},
		}
	case EventStop:
		return TransitionResult{
			NewPhase: PhaseIdle,
			Actions:  []Action{ActionCondense, ActionUpdateLastInteraction},
		}
	case EventGitCommit:
		if ctx.IsRebaseInProgress {
			return TransitionResult{NewPhase: PhaseActiveCommitted}
		}
		return TransitionResult{
			NewPhase: PhaseActiveCommitted,
			Actions:  []Action{ActionMigrateShadowBranch, ActionUpdateLastInteraction},
		}
	case EventSessionStart:
		return TransitionResult{
			NewPhase: PhaseActiveCommitted,
			Actions:  []Action{ActionWarnStaleSession},
		}
	case EventSessionStop:
		return TransitionResult{
			NewPhase: PhaseEnded,
			Actions:  []Action{ActionUpdateLastInteraction},
		}
	default:
		return TransitionResult{NewPhase: PhaseActiveCommitted}
	}
}

func transitionFromEnded(event Event, ctx TransitionContext) TransitionResult {
	switch event {
	case EventUserPromptSubmit:
		return TransitionResult{
			NewPhase: PhaseActive,
			Actions:  []Action{ActionClearEndedAt, ActionUpdateLastInteraction},
		}
	case EventStop:
		// Stop while ended is a no-op.
		return TransitionResult{NewPhase: PhaseEnded}
	case EventGitCommit:
		if ctx.IsRebaseInProgress {
			return TransitionResult{NewPhase: PhaseEnded}
		}
		if ctx.HasFilesTouched {
			return TransitionResult{
				NewPhase: PhaseEnded,
				Actions:  []Action{ActionCondenseIfFilesTouched, ActionUpdateLastInteraction},
			}
		}
		return TransitionResult{
			NewPhase: PhaseEnded,
			Actions:  []Action{ActionDiscardIfNoFiles, ActionUpdateLastInteraction},
		}
	case EventSessionStart:
		return TransitionResult{
			NewPhase: PhaseIdle,
			Actions:  []Action{ActionClearEndedAt},
		}
	case EventSessionStop:
		// Already ended, no-op.
		return TransitionResult{NewPhase: PhaseEnded}
	default:
		return TransitionResult{NewPhase: PhaseEnded}
	}
}

// MermaidDiagram generates a Mermaid state diagram from the transition table.
// The diagram is derived by calling Transition() for all (phase, event, context)
// combinations, so it is always in sync with the implementation.
func MermaidDiagram() string {
	var b strings.Builder
	b.WriteString("stateDiagram-v2\n")

	// State declarations with descriptions.
	b.WriteString("    state \"IDLE\" as idle\n")
	b.WriteString("    state \"ACTIVE\" as active\n")
	b.WriteString("    state \"ACTIVE_COMMITTED\" as active_committed\n")
	b.WriteString("    state \"ENDED\" as ended\n")
	b.WriteString("\n")

	// Context variants for GitCommit: rebase, files/no-files.
	type contextVariant struct {
		label string
		ctx   TransitionContext
	}

	// For each phase/event, generate edges.
	for _, phase := range allPhases {
		for _, event := range allEvents {
			var variants []contextVariant
			if event == EventGitCommit {
				variants = []contextVariant{
					{"", TransitionContext{HasFilesTouched: true, IsRebaseInProgress: false}},
					{"[no files]", TransitionContext{HasFilesTouched: false, IsRebaseInProgress: false}},
					{"[rebase]", TransitionContext{IsRebaseInProgress: true}},
				}
			} else {
				variants = []contextVariant{
					{"", TransitionContext{}},
				}
			}

			for _, v := range variants {
				result := Transition(phase, event, v.ctx)

				// Build edge label.
				label := event.String()
				if v.label != "" {
					label += " " + v.label
				}
				if len(result.Actions) > 0 {
					actionNames := make([]string, 0, len(result.Actions))
					for _, a := range result.Actions {
						actionNames = append(actionNames, a.String())
					}
					label += " / " + strings.Join(actionNames, ", ")
				}

				from := string(phase)
				to := string(result.NewPhase)

				fmt.Fprintf(&b, "    %s --> %s : %s\n", from, to, label)
			}
		}
	}

	return b.String()
}

package session

import (
	"os"
	"path/filepath"
	"runtime"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestPhaseFromString(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name  string
		input string
		want  Phase
	}{
		{name: "active", input: "active", want: PhaseActive},
		{name: "active_committed", input: "active_committed", want: PhaseActiveCommitted},
		{name: "idle", input: "idle", want: PhaseIdle},
		{name: "ended", input: "ended", want: PhaseEnded},
		{name: "empty_string_defaults_to_idle", input: "", want: PhaseIdle},
		{name: "unknown_string_defaults_to_idle", input: "bogus", want: PhaseIdle},
		{name: "uppercase_treated_as_unknown", input: "ACTIVE", want: PhaseIdle},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			got := PhaseFromString(tt.input)
			assert.Equal(t, tt.want, got)
		})
	}
}

func TestPhase_IsActive(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name  string
		phase Phase
		want  bool
	}{
		{name: "active_is_active", phase: PhaseActive, want: true},
		{name: "active_committed_is_active", phase: PhaseActiveCommitted, want: true},
		{name: "idle_is_not_active", phase: PhaseIdle, want: false},
		{name: "ended_is_not_active", phase: PhaseEnded, want: false},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			assert.Equal(t, tt.want, tt.phase.IsActive())
		})
	}
}

func TestEvent_String(t *testing.T) {
	t.Parallel()

	tests := []struct {
		event Event
		want  string
	}{
		{EventUserPromptSubmit, "UserPromptSubmit"},
		{EventStop, "Stop"},
		{EventGitCommit, "GitCommit"},
		{EventSessionStart, "SessionStart"},
		{EventSessionStop, "SessionStop"},
	}

	for _, tt := range tests {
		t.Run(tt.want, func(t *testing.T) {
			t.Parallel()
			assert.Equal(t, tt.want, tt.event.String())
		})
	}
}

func TestAction_String(t *testing.T) {
	t.Parallel()

	tests := []struct {
		action Action
		want   string
	}{
		{ActionCondense, "Condense"},
		{ActionCondenseIfFilesTouched, "CondenseIfFilesTouched"},
		{ActionDiscardIfNoFiles, "DiscardIfNoFiles"},
		{ActionMigrateShadowBranch, "MigrateShadowBranch"},
		{ActionWarnStaleSession, "WarnStaleSession"},
		{ActionClearEndedAt, "ClearEndedAt"},
		{ActionUpdateLastInteraction, "UpdateLastInteraction"},
	}

	for _, tt := range tests {
		t.Run(tt.want, func(t *testing.T) {
			t.Parallel()
			assert.Equal(t, tt.want, tt.action.String())
		})
	}
}

func TestTransition(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name        string
		current     Phase
		event       Event
		ctx         TransitionContext
		wantPhase   Phase
		wantActions []Action
	}{
		// --- IDLE transitions ---
		{
			name:        "IDLE_UserPromptSubmit_transitions_to_ACTIVE",
			current:     PhaseIdle,
			event:       EventUserPromptSubmit,
			wantPhase:   PhaseActive,
			wantActions: []Action{ActionUpdateLastInteraction},
		},
		{
			name:        "IDLE_GitCommit_triggers_condense",
			current:     PhaseIdle,
			event:       EventGitCommit,
			ctx:         TransitionContext{IsRebaseInProgress: false},
			wantPhase:   PhaseIdle,
			wantActions: []Action{ActionCondense, ActionUpdateLastInteraction},
		},
		{
			name:        "IDLE_GitCommit_rebase_skips_everything",
			current:     PhaseIdle,
			event:       EventGitCommit,
			ctx:         TransitionContext{IsRebaseInProgress: true},
			wantPhase:   PhaseIdle,
			wantActions: nil,
		},
		{
			name:        "IDLE_SessionStop_transitions_to_ENDED",
			current:     PhaseIdle,
			event:       EventSessionStop,
			wantPhase:   PhaseEnded,
			wantActions: []Action{ActionUpdateLastInteraction},
		},
		{
			name:        "IDLE_SessionStart_is_noop",
			current:     PhaseIdle,
			event:       EventSessionStart,
			wantPhase:   PhaseIdle,
			wantActions: nil,
		},
		{
			name:        "IDLE_Stop_is_noop",
			current:     PhaseIdle,
			event:       EventStop,
			wantPhase:   PhaseIdle,
			wantActions: nil,
		},

		// --- ACTIVE transitions ---
		{
			name:        "ACTIVE_UserPromptSubmit_stays_ACTIVE",
			current:     PhaseActive,
			event:       EventUserPromptSubmit,
			wantPhase:   PhaseActive,
			wantActions: []Action{ActionUpdateLastInteraction},
		},
		{
			name:        "ACTIVE_Stop_transitions_to_IDLE",
			current:     PhaseActive,
			event:       EventStop,
			wantPhase:   PhaseIdle,
			wantActions: []Action{ActionUpdateLastInteraction},
		},
		{
			name:        "ACTIVE_GitCommit_transitions_to_ACTIVE_COMMITTED",
			current:     PhaseActive,
			event:       EventGitCommit,
			ctx:         TransitionContext{IsRebaseInProgress: false},
			wantPhase:   PhaseActiveCommitted,
			wantActions: []Action{ActionMigrateShadowBranch, ActionUpdateLastInteraction},
		},
		{
			name:        "ACTIVE_GitCommit_rebase_skips_everything",
			current:     PhaseActive,
			event:       EventGitCommit,
			ctx:         TransitionContext{IsRebaseInProgress: true},
			wantPhase:   PhaseActive,
			wantActions: nil,
		},
		{
			name:        "ACTIVE_SessionStop_transitions_to_ENDED",
			current:     PhaseActive,
			event:       EventSessionStop,
			wantPhase:   PhaseEnded,
			wantActions: []Action{ActionUpdateLastInteraction},
		},
		{
			name:        "ACTIVE_SessionStart_warns_stale_session",
			current:     PhaseActive,
			event:       EventSessionStart,
			wantPhase:   PhaseActive,
			wantActions: []Action{ActionWarnStaleSession},
		},

		// --- ACTIVE_COMMITTED transitions ---
		{
			name:        "ACTIVE_COMMITTED_Stop_transitions_to_IDLE_with_condense",
			current:     PhaseActiveCommitted,
			event:       EventStop,
			wantPhase:   PhaseIdle,
			wantActions: []Action{ActionCondense, ActionUpdateLastInteraction},
		},
		{
			name:        "ACTIVE_COMMITTED_GitCommit_stays_with_migrate",
			current:     PhaseActiveCommitted,
			event:       EventGitCommit,
			ctx:         TransitionContext{IsRebaseInProgress: false},
			wantPhase:   PhaseActiveCommitted,
			wantActions: []Action{ActionMigrateShadowBranch, ActionUpdateLastInteraction},
		},
		{
			name:        "ACTIVE_COMMITTED_GitCommit_rebase_skips_everything",
			current:     PhaseActiveCommitted,
			event:       EventGitCommit,
			ctx:         TransitionContext{IsRebaseInProgress: true},
			wantPhase:   PhaseActiveCommitted,
			wantActions: nil,
		},
		{
			name:        "ACTIVE_COMMITTED_UserPromptSubmit_transitions_to_ACTIVE",
			current:     PhaseActiveCommitted,
			event:       EventUserPromptSubmit,
			wantPhase:   PhaseActive,
			wantActions: []Action{ActionUpdateLastInteraction},
		},
		{
			name:        "ACTIVE_COMMITTED_SessionStop_transitions_to_ENDED",
			current:     PhaseActiveCommitted,
			event:       EventSessionStop,
			wantPhase:   PhaseEnded,
			wantActions: []Action{ActionUpdateLastInteraction},
		},
		{
			name:        "ACTIVE_COMMITTED_SessionStart_warns_stale_session",
			current:     PhaseActiveCommitted,
			event:       EventSessionStart,
			wantPhase:   PhaseActiveCommitted,
			wantActions: []Action{ActionWarnStaleSession},
		},

		// --- ENDED transitions ---
		{
			name:        "ENDED_UserPromptSubmit_transitions_to_ACTIVE",
			current:     PhaseEnded,
			event:       EventUserPromptSubmit,
			wantPhase:   PhaseActive,
			wantActions: []Action{ActionClearEndedAt, ActionUpdateLastInteraction},
		},
		{
			name:        "ENDED_GitCommit_with_files_condenses",
			current:     PhaseEnded,
			event:       EventGitCommit,
			ctx:         TransitionContext{HasFilesTouched: true, IsRebaseInProgress: false},
			wantPhase:   PhaseEnded,
			wantActions: []Action{ActionCondenseIfFilesTouched, ActionUpdateLastInteraction},
		},
		{
			name:        "ENDED_GitCommit_without_files_discards",
			current:     PhaseEnded,
			event:       EventGitCommit,
			ctx:         TransitionContext{HasFilesTouched: false, IsRebaseInProgress: false},
			wantPhase:   PhaseEnded,
			wantActions: []Action{ActionDiscardIfNoFiles, ActionUpdateLastInteraction},
		},
		{
			name:        "ENDED_GitCommit_rebase_skips_everything",
			current:     PhaseEnded,
			event:       EventGitCommit,
			ctx:         TransitionContext{IsRebaseInProgress: true},
			wantPhase:   PhaseEnded,
			wantActions: nil,
		},
		{
			name:        "ENDED_SessionStart_transitions_to_IDLE",
			current:     PhaseEnded,
			event:       EventSessionStart,
			wantPhase:   PhaseIdle,
			wantActions: []Action{ActionClearEndedAt},
		},
		{
			name:        "ENDED_Stop_is_noop",
			current:     PhaseEnded,
			event:       EventStop,
			wantPhase:   PhaseEnded,
			wantActions: nil,
		},
		{
			name:        "ENDED_SessionStop_is_noop",
			current:     PhaseEnded,
			event:       EventSessionStop,
			wantPhase:   PhaseEnded,
			wantActions: nil,
		},

		// --- Empty phase (backward compat) treated as IDLE ---
		{
			name:        "empty_phase_UserPromptSubmit_treated_as_IDLE",
			current:     Phase(""),
			event:       EventUserPromptSubmit,
			wantPhase:   PhaseActive,
			wantActions: []Action{ActionUpdateLastInteraction},
		},
		{
			name:        "empty_phase_GitCommit_treated_as_IDLE",
			current:     Phase(""),
			event:       EventGitCommit,
			ctx:         TransitionContext{IsRebaseInProgress: false},
			wantPhase:   PhaseIdle,
			wantActions: []Action{ActionCondense, ActionUpdateLastInteraction},
		},
		{
			name:        "empty_phase_SessionStop_treated_as_IDLE",
			current:     Phase(""),
			event:       EventSessionStop,
			wantPhase:   PhaseEnded,
			wantActions: []Action{ActionUpdateLastInteraction},
		},
		{
			name:        "empty_phase_SessionStart_treated_as_IDLE",
			current:     Phase(""),
			event:       EventSessionStart,
			wantPhase:   PhaseIdle,
			wantActions: nil,
		},
		{
			name:        "empty_phase_Stop_treated_as_IDLE",
			current:     Phase(""),
			event:       EventStop,
			wantPhase:   PhaseIdle,
