func TestTransition(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name        string
		current     Phase
		event       Event
		ctx         TransitionContext
		wantPhase   Phase
		wantActions []Action
	}{
		// --- IDLE transitions ---
		{
			name:        "IDLE_UserPromptSubmit_transitions_to_ACTIVE",
			current:     PhaseIdle,
			event:       EventTurnStart,
			wantPhase:   PhaseActive,
			wantActions: []Action{ActionUpdateLastInteraction},
		},
		{
			name:        "IDLE_GitCommit_triggers_condense",
			current:     PhaseIdle,
			event:       EventGitCommit,
			ctx:         TransitionContext{IsRebaseInProgress: false},
			wantPhase:   PhaseIdle,
			wantActions: []Action{ActionCondense, ActionUpdateLastInteraction},
		},
		{
			name:        "IDLE_GitCommit_rebase_skips_everything",
			current:     PhaseIdle,
			event:       EventGitCommit,
			ctx:         TransitionContext{IsRebaseInProgress: true},
			wantPhase:   PhaseIdle,
			wantActions: nil,
		},
		{
			name:        "IDLE_SessionStop_transitions_to_ENDED",
			current:     PhaseIdle,
			event:       EventSessionStop,
			wantPhase:   PhaseEnded,
			wantActions: []Action{ActionUpdateLastInteraction},
		},
		{
			name:        "IDLE_SessionStart_is_noop",
			current:     PhaseIdle,
			event:       EventSessionStart,
			wantPhase:   PhaseIdle,
			wantActions: nil,
		},
		{
			name:        "IDLE_Stop_is_noop",
			current:     PhaseIdle,
			event:       EventTurnEnd,
			wantPhase:   PhaseIdle,
			wantActions: nil,
		},

		// --- ACTIVE transitions ---
		{
			name:        "ACTIVE_UserPromptSubmit_stays_ACTIVE",
			current:     PhaseActive,
			event:       EventTurnStart,
			wantPhase:   PhaseActive,
			wantActions: []Action{ActionUpdateLastInteraction},
		},
		{
			name:        "ACTIVE_Stop_transitions_to_IDLE",
			current:     PhaseActive,
			event:       EventTurnEnd,
			wantPhase:   PhaseIdle,
			wantActions: []Action{ActionUpdateLastInteraction},
		},
		{
			name:        "ACTIVE_GitCommit_transitions_to_ACTIVE_COMMITTED",
			current:     PhaseActive,
			event:       EventGitCommit,
			ctx:         TransitionContext{IsRebaseInProgress: false},
			wantPhase:   PhaseActiveCommitted,
			wantActions: []Action{ActionMigrateShadowBranch, ActionUpdateLastInteraction},
		},
		{
			name:        "ACTIVE_GitCommit_rebase_skips_everything",
			current:     PhaseActive,
			event:       EventGitCommit,
			ctx:         TransitionContext{IsRebaseInProgress: true},
			wantPhase:   PhaseActive,
			wantActions: nil,
		},
		{
			name:        "ACTIVE_SessionStop_transitions_to_ENDED",
			current:     PhaseActive,
			event:       EventSessionStop,
			wantPhase:   PhaseEnded,
			wantActions: []Action{ActionUpdateLastInteraction},
		},
		{
			name:        "ACTIVE_SessionStart_warns_stale_session",
			current:     PhaseActive,
			event:       EventSessionStart,
			wantPhase:   PhaseActive,
			wantActions: []Action{ActionWarnStaleSession},
		},

		// --- ACTIVE_COMMITTED transitions ---
		{
			name:        "ACTIVE_COMMITTED_Stop_transitions_to_IDLE_with_condense",
			current:     PhaseActiveCommitted,
			event:       EventTurnEnd,
			wantPhase:   PhaseIdle,
			wantActions: []Action{ActionCondense, ActionUpdateLastInteraction},
		},
		{
			name:        "ACTIVE_COMMITTED_GitCommit_stays_with_migrate",
			current:     PhaseActiveCommitted,
			event:       EventGitCommit,
			ctx:         TransitionContext{IsRebaseInProgress: false},
			wantPhase:   PhaseActiveCommitted,
			wantActions: []Action{ActionMigrateShadowBranch, ActionUpdateLastInteraction},
		},
		{
			name:        "ACTIVE_COMMITTED_GitCommit_rebase_skips_everything",
			current:     PhaseActiveCommitted,
			event:       EventGitCommit,
			ctx:         TransitionContext{IsRebaseInProgress: true},
			wantPhase:   PhaseActiveCommitted,
			wantActions: nil,
		},
		{
			name:        "ACTIVE_COMMITTED_UserPromptSubmit_transitions_to_ACTIVE",
			current:     PhaseActiveCommitted,
			event:       EventTurnStart,
			wantPhase:   PhaseActive,
			wantActions: []Action{ActionUpdateLastInteraction},
		},
		{
			name:        "ACTIVE_COMMITTED_SessionStop_transitions_to_ENDED",
			current:     PhaseActiveCommitted,
			event:       EventSessionStop,
			wantPhase:   PhaseEnded,
			wantActions: []Action{ActionUpdateLastInteraction},
		},
		{
			name:        "ACTIVE_COMMITTED_SessionStart_warns_stale_session",
			current:     PhaseActiveCommitted,
			event:       EventSessionStart,
			wantPhase:   PhaseActiveCommitted,
			wantActions: []Action{ActionWarnStaleSession},
		},

		// --- ENDED transitions ---
		{
			name:        "ENDED_UserPromptSubmit_transitions_to_ACTIVE",
			current:     PhaseEnded,
			event:       EventTurnStart,
			wantPhase:   PhaseActive,
			wantActions: []Action{ActionClearEndedAt, ActionUpdateLastInteraction},
		},
		{
			name:        "ENDED_GitCommit_with_files_condenses",
			current:     PhaseEnded,
			event:       EventGitCommit,
			ctx:         TransitionContext{HasFilesTouched: true, IsRebaseInProgress: false},
			wantPhase:   PhaseEnded,
			wantActions: []Action{ActionCondenseIfFilesTouched, ActionUpdateLastInteraction},
		},
		{
			name:        "ENDED_GitCommit_without_files_discards",
			current:     PhaseEnded,
			event:       EventGitCommit,
			ctx:         TransitionContext{HasFilesTouched: false, IsRebaseInProgress: false},
			wantPhase:   PhaseEnded,
			wantActions: []Action{ActionDiscardIfNoFiles, ActionUpdateLastInteraction},
		},
		{
			name:        "ENDED_GitCommit_rebase_skips_everything",
			current:     PhaseEnded,
			event:       EventGitCommit,
			ctx:         TransitionContext{IsRebaseInProgress: true},
			wantPhase:   PhaseEnded,
			wantActions: nil,
		},
		{
			name:        "ENDED_SessionStart_transitions_to_IDLE",
			current:     PhaseEnded,
			event:       EventSessionStart,
			wantPhase:   PhaseIdle,
			wantActions: []Action{ActionClearEndedAt},
		},
		{
			name:        "ENDED_Stop_is_noop",
			current:     PhaseEnded,
			event:       EventTurnEnd,
			wantPhase:   PhaseEnded,
			wantActions: nil,
		},
		{
			name:        "ENDED_SessionStop_is_noop",
			current:     PhaseEnded,
			event:       EventSessionStop,
			wantPhase:   PhaseEnded,
			wantActions: nil,
		},

		// --- Empty phase (backward compat) treated as IDLE ---
		{
			name:        "empty_phase_UserPromptSubmit_treated_as_IDLE",
			current:     Phase(""),
			event:       EventTurnStart,
			wantPhase:   PhaseActive,
			wantActions: []Action{ActionUpdateLastInteraction},
		},
		{
			name:        "empty_phase_GitCommit_treated_as_IDLE",
			current:     Phase(""),
			event:       EventGitCommit,
			ctx:         TransitionContext{IsRebaseInProgress: false},
			wantPhase:   PhaseIdle,
			wantActions: []Action{ActionCondense, ActionUpdateLastInteraction},
		},
		{
			name:        "empty_phase_SessionStop_treated_as_IDLE",
			current:     Phase(""),
			event:       EventSessionStop,
			wantPhase:   PhaseEnded,
			wantActions: []Action{ActionUpdateLastInteraction},
		},
		{
			name:        "empty_phase_SessionStart_treated_as_IDLE",
			current:     Phase(""),
			event:       EventSessionStart,
			wantPhase:   PhaseIdle,
			wantActions: nil,
		},
		{
			name:        "empty_phase_Stop_treated_as_IDLE",
			current:     Phase(""),
			event:       EventTurnEnd,
			wantPhase:   PhaseIdle,
			wantActions: nil,
		},

		// --- Unknown phase treated as IDLE ---
		{
			name:        "unknown_phase_UserPromptSubmit_treated_as_IDLE",
			current:     Phase("bogus"),
			event:       EventTurnStart,
			wantPhase:   PhaseActive,
			wantActions: []Action{ActionUpdateLastInteraction},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()

			result := Transition(tt.current, tt.event, tt.ctx)

			assert.Equal(t, tt.wantPhase, result.NewPhase, "unexpected NewPhase")
			assert.Equal(t, tt.wantActions, result.Actions, "unexpected Actions")
		})
	}
}

