    13→// Session state management functions shared across all strategies.
    14→// SessionState is stored in .git/entire-sessions/{session_id}.json
    15→
    16→// getSessionStateDir returns the path to the session state directory.
    17→// This is stored in the git common dir so it's shared across all worktrees.
    18→func getSessionStateDir() (string, error) {
    19→	commonDir, err := GetGitCommonDir()
    20→	if err != nil {
    21→		return "", err
    22→	}
    23→	return filepath.Join(commonDir, sessionStateDirName), nil
    24→}
    25→
    26→// sessionStateFile returns the path to a session state file.
    27→func sessionStateFile(sessionID string) (string, error) {
    28→	stateDir, err := getSessionStateDir()
    29→	if err != nil {
    30→		return "", err
    31→	}
    32→	return filepath.Join(stateDir, sessionID+".json"), nil
    33→}
    34→
    35→// LoadSessionState loads the session state for the given session ID.
    36→// Returns (nil, nil) when session file doesn't exist (not an error condition).
    37→func LoadSessionState(sessionID string) (*SessionState, error) {
    38→	// Validate session ID to prevent path traversal
    39→	if err := validation.ValidateSessionID(sessionID); err != nil {
    40→		return nil, fmt.Errorf("invalid session ID: %w", err)
    41→	}
    42→
    43→	stateFile, err := sessionStateFile(sessionID)
    44→	if err != nil {
    45→		return nil, fmt.Errorf("failed to get session state file path: %w", err)
    46→	}
    47→
    48→	data, err := os.ReadFile(stateFile) //nolint:gosec // stateFile is derived from sessionID, not user input
    49→	if os.IsNotExist(err) {
    50→		return nil, nil //nolint:nilnil // nil,nil indicates session not found (expected case)
    51→	}
    52→	if err != nil {
    53→		return nil, fmt.Errorf("failed to read session state: %w", err)
    54→	}
    55→
    56→	var state SessionState
    57→	if err := json.Unmarshal(data, &state); err != nil {
    58→		return nil, fmt.Errorf("failed to unmarshal session state: %w", err)
    59→	}
    60→	state.NormalizeAfterLoad()
    61→	return &state, nil
    62→}
    63→
    64→// SaveSessionState saves the session state atomically.
    65→func SaveSessionState(state *SessionState) error {
    66→	// Validate session ID to prevent path traversal
    67→	if err := validation.ValidateSessionID(state.SessionID); err != nil {
    68→		return fmt.Errorf("invalid session ID: %w", err)
    69→	}
    70→
    71→	stateDir, err := getSessionStateDir()
    72→	if err != nil {
    73→		return fmt.Errorf("failed to get session state directory: %w", err)
    74→	}
    75→
    76→	if err := os.MkdirAll(stateDir, 0o750); err != nil {
    77→		return fmt.Errorf("failed to create session state directory: %w", err)
    78→	}
    79→
    80→	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
    81→	if err != nil {
    82→		return fmt.Errorf("failed to marshal session state: %w", err)
    83→	}
    84→
    85→	stateFile, err := sessionStateFile(state.SessionID)
    86→	if err != nil {
    87→		return fmt.Errorf("failed to get session state file path: %w", err)
    88→	}
    89→
    90→	// Atomic write: write to temp file, then rename
    91→	tmpFile := stateFile + ".tmp"
    92→	if err := os.WriteFile(tmpFile, data, 0o600); err != nil {
    93→		return fmt.Errorf("failed to write session state: %w", err)
    94→	}
    95→	if err := os.Rename(tmpFile, stateFile); err != nil {
    96→		return fmt.Errorf("failed to rename session state file: %w", err)
    97→	}
    98→	return nil
    99→}
   100→
   101→// ClearSessionState removes the session state file for the given session ID.
   102→func ClearSessionState(sessionID string) error {
   103→	// Validate session ID to prevent path traversal
   104→	if err := validation.ValidateSessionID(sessionID); err != nil {
   105→		return fmt.Errorf("invalid session ID: %w", err)
   106→	}
   107→
   108→	stateFile, err := sessionStateFile(sessionID)
   109→	if err != nil {
   110→		return fmt.Errorf("failed to get session state file path: %w", err)
   111→	}
   112→
   113→	if err := os.Remove(stateFile); err != nil {
   114→		if os.IsNotExist(err) {
   115→			return nil // Already gone, not an error
   116→		}
   117→		return fmt.Errorf("failed to remove session state file: %w", err)
   118→	}
   119→	return nil
   120→}
